def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Group consecutive rows containing non-background cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Find equally tall bands where one contains a rectangular extension
    # missing from the other, then mark that extension.
    best = None
    for i in range(len(bands)):
        a0, a1 = bands[i]
        ah = a1 - a0
        for j in range(i + 1, len(bands)):
            b0, b1 = bands[j]
            if b1 - b0 != ah:
                continue
            for dst0, src0 in ((a0, b0), (b0, a0)):
                for top in range(ah):
                    for bottom in range(top, ah):
                        for left in range(w):
                            for right in range(left, w):
                                ok = True
                                for dr in range(top, bottom + 1):
                                    for c in range(left, right + 1):
                                        if (grid[src0 + dr][c] == bg or
                                                grid[dst0 + dr][c] != bg):
                                            ok = False
                                            break
                                    if not ok:
                                        break
                                area = (bottom - top + 1) * (right - left + 1)
                                if ok and (best is None or area > best[0]):
                                    best = (area, dst0, top, bottom, left, right)

    if best:
        _, dst0, top, bottom, left, right = best
        for dr in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[dst0 + dr][c] = 1
    return out
